  function boundaryAdvice(flower){
    return `「${flower.watch[0]}」「${flower.watch[1]}」が続く時は、頑張り方ではなく予定・役割・人との距離を見直すタイミングです。返事をすぐにしない、期限を相談する、担当を分けるなど、負担を具体的に一つ減らしてみてください。`;
  }
